/**
 * Gated form access codes are generated by the server (at least 128 bits), stored as a
 * hash compared in constant time, never returned after creation, and old user-chosen codes
 * must be regenerated before the form opens again.
 */
import bcrypt from 'bcryptjs';
import request from 'supertest';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

import { prisma } from '../../config/database';
import app from '../../index';
import { cleanupTestContext, createTestContext, type TestContext } from '../../test/factory';
import { authGet, authPatch, authPost } from '../../test/helpers';

import { clientKey, parseTrustProxy } from './client-ip';

describe('Form access codes', () => {
  let ctx: TestContext;
  const pub = (method: 'get' | 'post', path: string) =>
    request(app)[method](`/api${path}`).set('X-Requested-With', 'XMLHttpRequest');

  beforeAll(async () => {
    ctx = await createTestContext(`fsecret${Date.now()}`);
  });

  afterAll(async () => {
    await cleanupTestContext(ctx);
  });

  it('refuses a chosen code and generates one of at least 128 bits', async () => {
    const P = `/api/projects/${ctx.projectId}/forms`;
    const chosen = await authPost(P, ctx.owner.token, {
      name: 'Chosen',
      slug: `chosen-${Date.now()}`,
      authMode: 'TOKEN_GATED',
      sharedSecret: '1234',
    });
    expect(chosen.status).toBe(400);

    const slug = `gen-${Date.now()}`;
    const created = await authPost(P, ctx.owner.token, {
      name: 'Generated',
      slug,
      authMode: 'TOKEN_GATED',
    });
    expect(created.status).toBe(201);
    const code = created.body.accessCode as string;
    expect(code).toMatch(/^[A-Za-z0-9_-]{22,}$/);
    expect(created.body.sharedSecret).toBeUndefined();
    const read = await authGet(`${P}/${created.body.id}`, ctx.owner.token);
    expect(JSON.stringify(read.body)).not.toContain('sharedSecret');

    await prisma.form.update({ where: { id: created.body.id }, data: { status: 'PUBLISHED' } });
    const ok = await pub('post', `/f/${slug}/submit`).send({ data: { a: 1 }, secret: code });
    expect(ok.status).toBe(201);

    // Regenerating replaces the code
    const regen = await authPatch(`${P}/${created.body.id}`, ctx.owner.token, {
      regenerateSecret: true,
    });
    expect(regen.status).toBe(200);
    expect(regen.body.accessCode).toMatch(/^[A-Za-z0-9_-]{22,}$/);
    const old = await pub('post', `/f/${slug}/submit`).send({ data: { a: 2 }, secret: code });
    expect(old.status).toBe(401);
  });

  it('keeps a form with an old chosen code closed until it is regenerated', async () => {
    const slug = `legacy-${Date.now()}`;
    await prisma.form.create({
      data: {
        projectId: ctx.projectId,
        name: 'Legacy',
        slug,
        createdById: ctx.owner.id,
        status: 'PUBLISHED',
        authMode: 'TOKEN_GATED',
        sharedSecret: await bcrypt.hash('1234', 4),
      },
    });
    const get = await pub('get', `/f/${slug}`).set('X-Form-Secret', '1234');
    expect(get.body.locked).toBe(true);
    const submit = await pub('post', `/f/${slug}/submit`).send({ data: {}, secret: '1234' });
    expect(submit.status).toBe(403);
  });

  it('keys IPv6 clients by /64 and reads TRUST_PROXY', () => {
    expect(clientKey('2001:db8:1:2:aaaa::1')).toBe(clientKey('2001:db8:1:2:bbbb:cccc:dddd:2'));
    expect(clientKey('2001:db8:1:3::1')).not.toBe(clientKey('2001:db8:1:2::1'));
    expect(clientKey('::ffff:203.0.113.7')).toBe('203.0.113.7');
    expect(clientKey('203.0.113.7')).toBe('203.0.113.7');

    expect(parseTrustProxy(undefined, 'production')).toBe(1);
    expect(parseTrustProxy(undefined, 'development')).toBeUndefined();
    expect(parseTrustProxy('2', 'development')).toBe(2);
    expect(parseTrustProxy('true', 'development')).toBe(true);
    expect(parseTrustProxy('false', 'production')).toBe(false);
    expect(parseTrustProxy('loopback, uniquelocal', 'development')).toBe('loopback, uniquelocal');
  });

  it('a partial update keeps a gated form gated', async () => {
    const P = `/api/projects/${ctx.projectId}/forms`;
    const created = await authPost(P, ctx.owner.token, {
      name: 'Stay gated',
      slug: `stay-${Date.now()}`,
      authMode: 'TOKEN_GATED',
    });
    const renamed = await authPatch(`${P}/${created.body.id}`, ctx.owner.token, {
      name: 'Renamed',
    });
    expect(renamed.status).toBe(200);
    const form = await prisma.form.findUniqueOrThrow({ where: { id: created.body.id } });
    expect(form.authMode).toBe('TOKEN_GATED');
  });
});
